const PDFDocument = require("pdfkit");

const COLORS = {
  ink: "#202020",
  body: "#4F4A40",
  muted: "#827760",
  gold: "#F5C15C",
  goldDark: "#9B6C12",
  cream: "#FFF9ED",
  pale: "#F7F4ED",
  border: "#E7CF99",
  white: "#FFFFFF",
};

const PAGE_WIDTH = 595.28;
const PAGE_HEIGHT = 841.89;
const LEFT = 46;
const RIGHT = PAGE_WIDTH - 46;
const CONTENT_WIDTH = RIGHT - LEFT;
const BOTTOM_LIMIT = PAGE_HEIGHT - 82;
const LOGO_PNG = Buffer.from("", "base64");

const PLAN_PRICE_FALLBACKS = {
  "website-designing:standard-landing-page": 24400,
  "website-designing:premium-landing-page": 34400,
  "website-designing:advanced-landing-page": 44400,
  "ecommerce-website:small-startup": 31400,
  "ecommerce-website:business-store": 41400,
  "ecommerce-website:enterprise-store": 51400,
  "website-development:basic-development": 34999,
  "website-development:business-development": 49999,
  "website-development:enterprise-development": 69999,
};

const PLAN_PRICING_CATALOG = {
  "website-designing": {
    "standard-landing-page": { items: { website: 18400, domain: 1500, hosting: 4500, businessEmail: "Included" }, extraPagePrice: 2000 },
    "premium-landing-page": { items: { website: 24400, domain: 1500, hosting: 8500, businessEmail: "Included" }, extraPagePrice: 2000 },
    "advanced-landing-page": { items: { website: 34400, domain: 1500, hosting: 8500, businessEmail: "Included" }, extraPagePrice: 2000 },
  },
  "website-development": {
    "basic-development": { items: { website: 24999, domain: 1500, hosting: 8500, businessEmail: "Included" }, extraPagePrice: 2000 },
    "business-development": { items: { website: 39999, domain: 1500, hosting: 8500, businessEmail: "Included" }, extraPagePrice: 2000 },
    "enterprise-development": { items: { website: 59999, domain: 1500, hosting: 8500, businessEmail: "Included" }, extraPagePrice: 2000 },
  },
  "ecommerce-website": {
    "small-startup": { items: { website: 21400, domain: 1500, hosting: 8500, businessEmail: "Included" }, extraPagePrice: 2000, perProductPrice: 15, mockupPrice: 250 },
    "business-store": { items: { website: 31400, domain: 1500, hosting: 8500, businessEmail: "Included" }, extraPagePrice: 2000, perProductPrice: 15, mockupPrice: 200 },
    "enterprise-store": { items: { website: 41400, domain: 1500, hosting: 8500, businessEmail: "Included" }, extraPagePrice: 2000, perProductPrice: 15, mockupPrice: 150 },
  },
};

function humanize(value) {
  return String(value ?? "")
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .replace(/[-_]+/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function displayValue(value) {
  if (Array.isArray(value)) return value.map(displayValue).filter(Boolean).join(", ");
  if (value && typeof value === "object") {
    return Object.entries(value)
      .map(([key, innerValue]) => `${humanize(key)}: ${displayValue(innerValue)}`)
      .filter((entry) => !entry.endsWith(": "))
      .join("; ");
  }
  return typeof value === "string" ? humanize(value) : String(value ?? "");
}

function getSelectionRows(details = {}) {
  if (!details || typeof details !== "object" || Array.isArray(details)) return [];

  const rows = [];
  const labels = {
    extraPages: "Additional pages",
    products: "Products",
    mockups: "Mockups",
    quantity: "Quantity",
    months: "Duration (months)",
    platforms: "Platforms",
    selectedItems: "Selected services",
  };

  if (details.selections && typeof details.selections === "object") {
    for (const [key, value] of Object.entries(details.selections)) {
      const formatted = displayValue(value);
      if (formatted) rows.push([humanize(key), formatted]);
    }
  }

  for (const [key, value] of Object.entries(details)) {
    if (["selections", "selectedPlan", "pincode", "note"].includes(key)) continue;
    const formatted = displayValue(value);
    if (formatted) rows.push([labels[key] || humanize(key), formatted]);
  }

  return rows;
}

function formatQuotationNumber(quotation) {
  const supplied = quotation.quotationNumber || quotation.quoteNumber || quotation._id || quotation.id;
  if (!supplied) return "-";
  const raw = String(supplied);
  if (/^[a-f0-9]{24}$/i.test(raw)) return `DWS-${raw.slice(-8).toUpperCase()}`;
  if (raw.length <= 16) return raw;
  return `DWS-${raw.replace(/[^a-z0-9]/gi, "").slice(-8).toUpperCase()}`;
}

function formatDate(value) {
  const date = value ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) return "-";
  return date.toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

function formatMoney(value) {
  const amount = Number(value || 0);
  const hasPaise = Math.abs(amount % 1) > 0.000001;
  return `Rs. ${amount.toLocaleString("en-IN", {
    minimumFractionDigits: hasPaise ? 2 : 0,
    maximumFractionDigits: 2,
  })}`;
}

function drawPageHeader(doc, quotation, continued = false) {
  if (continued) {
    doc
      .image(LOGO_PNG, LEFT, 17, { fit: [190, 48] })
      .font("Helvetica-Bold")
      .fontSize(12)
      .fillColor(COLORS.ink)
      .text("QUOTATION - CONTINUED", LEFT, 58, {
        width: CONTENT_WIDTH,
        align: "right",
        characterSpacing: 0.6,
      });
    doc.moveTo(LEFT, 83).lineTo(RIGHT, 83).strokeColor(COLORS.gold).lineWidth(1.2).stroke();
    doc.y = 105;
    return;
  }

  doc.image(LOGO_PNG, LEFT, 18, { fit: [180, 66] });
  doc
    .font("Helvetica-Bold")
    .fontSize(23)
    .fillColor(COLORS.ink)
    .text("QUOTATION", RIGHT - 235, 25, {
      width: 235,
      align: "right",
      characterSpacing: 0.6,
    });
  doc
    .font("Helvetica")
    .fontSize(8)
    .fillColor(COLORS.body)
    .text(`No. ${formatQuotationNumber(quotation)}`, RIGHT - 235, 58, {
      width: 235,
      align: "right",
      lineBreak: false,
    });
  doc
    .font("Helvetica")
    .fontSize(8)
    .fillColor(COLORS.body)
    .text(`Date: ${formatDate(quotation.createdAt)}`, RIGHT - 235, 72, {
      width: 235,
      align: "right",
      lineBreak: false,
    });
  doc.moveTo(LEFT, 96).lineTo(RIGHT, 96).strokeColor(COLORS.gold).lineWidth(1.2).stroke();
  doc.y = 116;
}

function drawFooter(doc, pageNumber, pageCount) {
  const previousBottomMargin = doc.page.margins.bottom;
  doc.page.margins.bottom = 0;
  doc
    .moveTo(LEFT, PAGE_HEIGHT - 53)
    .lineTo(RIGHT, PAGE_HEIGHT - 53)
    .strokeColor(COLORS.border)
    .lineWidth(0.7)
    .stroke();
  doc
    .font("Helvetica")
    .fontSize(8)
    .fillColor(COLORS.muted)
    .text(
      "Thank you for your interest in Discover Websoft.",
      LEFT,
      PAGE_HEIGHT - 40,
      { width: CONTENT_WIDTH - 50, lineBreak: false }
    );
  doc
    .font("Helvetica-Bold")
    .fontSize(8)
    .fillColor(COLORS.muted)
    .text(`${pageNumber} / ${pageCount}`, RIGHT - 50, PAGE_HEIGHT - 40, {
      width: 50,
      align: "right",
      lineBreak: false,
    });
  doc.page.margins.bottom = previousBottomMargin;
}

function ensureSpace(doc, height, quotation) {
  if (doc.y + height <= BOTTOM_LIMIT) return false;
  doc.addPage();
  drawPageHeader(doc, quotation, true);
  return true;
}

function drawSectionTitle(doc, title) {
  const y = doc.y;
  doc
    .rect(LEFT, y - 1, 4, 13)
    .fill(COLORS.goldDark);
  doc
    .font("Helvetica-Bold")
    .fontSize(11)
    .fillColor(COLORS.ink)
    .text(title.toUpperCase(), LEFT + 12, y, { characterSpacing: 0.7 });
  doc.y = y + 26;
}

function drawInfoCards(doc, quotation) {
  const cardY = doc.y;
  const gap = 12;
  const cardWidth = (CONTENT_WIDTH - gap) / 2;
  const cardHeight = 90;
  const customerX = LEFT;
  const serviceX = LEFT + cardWidth + gap;
  const customerName = quotation.user?.name || quotation.customerName || "Guest";
  const customerEmail = quotation.user?.email || quotation.customerEmail || "-";
  const customerPhone = quotation.user?.phone || quotation.customerPhone || "-";
  const service = humanize(quotation.serviceSlug || "-");
  const plan = quotation.planName || humanize(quotation.planSlug || "-");

  for (const x of [customerX, serviceX]) {
    doc
      .roundedRect(x, cardY, cardWidth, cardHeight, 9)
      .fillAndStroke(COLORS.pale, COLORS.border);
  }

  doc
    .font("Helvetica-Bold")
    .fontSize(8)
    .fillColor(COLORS.goldDark)
    .text("PREPARED FOR", customerX + 13, cardY + 12, { characterSpacing: 0.7 });
  doc
    .font("Helvetica-Bold")
    .fontSize(11)
    .fillColor(COLORS.ink)
    .text(customerName, customerX + 13, cardY + 29, {
      width: cardWidth - 26,
      height: 14,
      ellipsis: true,
    });
  doc
    .font("Helvetica")
    .fontSize(8)
    .fillColor(COLORS.body)
    .text(customerEmail, customerX + 13, cardY + 50, {
      width: cardWidth - 26,
      height: 11,
      ellipsis: true,
    })
    .text(customerPhone, customerX + 13, cardY + 68, {
      width: cardWidth - 26,
      height: 11,
      ellipsis: true,
    });

  doc
    .font("Helvetica-Bold")
    .fontSize(8)
    .fillColor(COLORS.goldDark)
    .text("QUOTE DETAILS", serviceX + 13, cardY + 12, { characterSpacing: 0.7 });
  doc
    .font("Helvetica-Bold")
    .fontSize(11)
    .fillColor(COLORS.ink)
    .text(service, serviceX + 13, cardY + 29, {
      width: cardWidth - 26,
      height: 14,
      ellipsis: true,
    });
  doc
    .font("Helvetica")
    .fontSize(8)
    .fillColor(COLORS.body)
    .text(`Plan: ${plan}`, serviceX + 13, cardY + 50, {
      width: cardWidth - 26,
      height: 12,
      ellipsis: true,
    });
  doc.y = cardY + cardHeight + 22;
}

function getCustomPricingRows(quotation) {
  const details = quotation.details && typeof quotation.details === "object" ? quotation.details : {};
  const serviceSlug = quotation.serviceSlug || "";
  const selections = details.selections && typeof details.selections === "object"
    ? details.selections
    : {};
  const catalog = PLAN_PRICING_CATALOG[serviceSlug];
  const rows = [];

  if (catalog && (quotation.quotationType === "website" || quotation.quotationType === "ecommerce")) {
    const labels = {
      website: "Website",
      domain: "Domain",
      hosting: "Hosting",
      businessEmail: "Business email",
    };

    for (const [key, selectedPlanSlug] of Object.entries(selections)) {
      if (!labels[key] || typeof selectedPlanSlug !== "string") continue;
      const value = catalog[selectedPlanSlug]?.items?.[key];
      if (typeof value === "number" && value > 0) {
        rows.push({ item: labels[key], quantity: 1, price: value });
      } else if (value === "Included") {
        rows.push({ item: labels[key], quantity: 1, price: "Included" });
      }
    }

    const websitePlanSlug = typeof selections.website === "string"
      ? selections.website
      : quotation.planSlug;
    const websitePlan = catalog[websitePlanSlug] || catalog[quotation.planSlug];
    const extraPages = Math.max(0, Number(details.extraPages) || 0);
    if (extraPages > 0 && websitePlan?.extraPagePrice) {
      rows.push({
        item: "Additional pages",
        quantity: extraPages,
        price: extraPages * websitePlan.extraPagePrice,
      });
    }

    // Products and mockups are ecommerce-only options. PlanPage initializes
    // these fields for every service, so do not render them for other services.
    if (serviceSlug === "ecommerce-website") {
      const products = Math.max(0, Number(details.products) || 0);
      const mockups = Math.max(0, Number(details.mockups) || 0);
      if (products > 0 && websitePlan?.perProductPrice) {
        rows.push({ item: "Products", quantity: products, price: products * websitePlan.perProductPrice });
      }
      if (mockups > 0 && websitePlan?.mockupPrice) {
        rows.push({ item: "Product mockups", quantity: mockups, price: mockups * websitePlan.mockupPrice });
      }
    }
  }

  const subtotal = Number(quotation.subtotal);
  if (rows.length && Number.isFinite(subtotal) && subtotal >= 0) {
    const itemizedTotal = rows.reduce((sum, row) => sum + (typeof row.price === "number" ? row.price : 0), 0);
    const difference = subtotal - itemizedTotal;
    if (Math.abs(difference) <= 1) return rows;
    if (difference > 1) {
      rows.push({ item: "Other selected items", quantity: 1, price: difference });
      return rows;
    }
    // If the catalog changed after this quotation was saved, show its saved
    // subtotal as one accurate line instead of printing stale item prices.
  }

  const quantity = Math.max(1, Number(details.quantity) || 1);
  const savedPrice = Number.isFinite(subtotal) && subtotal >= 0
    ? subtotal
    : (resolvePlanPrice(quotation) ?? null);
  let item = quotation.planName || humanize(quotation.planSlug || quotation.serviceSlug || "Quotation");
  if (serviceSlug === "ecommerce-website") {
    const extras = [];
    if (Number(details.products) > 0) extras.push(`${Number(details.products)} products`);
    if (Number(details.mockups) > 0) extras.push(`${Number(details.mockups)} mockups`);
    if (extras.length) item += ` (${extras.join(", ")})`;
  }
  return [{ item, quantity, price: savedPrice == null ? "-" : savedPrice / quantity }];
}

function drawPricingTableHeader(doc) {
  const headerY = doc.y;
  const noX = LEFT + 13;
  const itemX = LEFT + 62;
  const priceWidth = 78;
  const priceX = RIGHT - 18 - priceWidth;
  const quantityWidth = 66;
  const quantityX = priceX - 12 - quantityWidth;
  const itemWidth = quantityX - itemX - 12;
  doc.roundedRect(LEFT, headerY, CONTENT_WIDTH, 27, 5).fill(COLORS.gold);
  doc.font("Helvetica-Bold").fontSize(8).fillColor(COLORS.ink);
  doc.text("S. NO.", noX, headerY + 9, { width: 40, lineBreak: false });
  doc.text("ITEM", itemX, headerY + 9, { width: itemWidth - 8, lineBreak: false, characterSpacing: 0.4 });
  doc.text("QUANTITY", quantityX, headerY + 9, { width: quantityWidth, align: "center", lineBreak: false });
  doc.text("PRICE", priceX, headerY + 9, { width: priceWidth, align: "right", lineBreak: false });
  doc.y = headerY + 27;
}

function drawPricingTable(doc, quotation, rows) {
  drawSectionTitle(doc, "Quotation items");
  drawPricingTableHeader(doc);
  const noX = LEFT + 13;
  const itemX = LEFT + 62;
  const priceWidth = 78;
  const priceX = RIGHT - 18 - priceWidth;
  const quantityWidth = 66;
  const quantityX = priceX - 12 - quantityWidth;
  const itemWidth = quantityX - itemX - 12;

  rows.forEach((row, index) => {
    doc.font("Helvetica");
    const itemHeight = doc.heightOfString(String(row.item), { width: itemWidth - 8, fontSize: 9, lineGap: 2 });
    const rowHeight = Math.max(34, itemHeight + 16);
    if (ensureSpace(doc, rowHeight + 45, quotation)) {
      drawSectionTitle(doc, "Quotation items - continued");
      drawPricingTableHeader(doc);
    }
    const rowY = doc.y;
    if (index % 2 === 0) doc.rect(LEFT, rowY, CONTENT_WIDTH, rowHeight).fill(COLORS.cream);
    doc.font("Helvetica").fontSize(9).fillColor(COLORS.muted)
      .text(String(index + 1).padStart(2, "0"), noX, rowY + 10, { width: 36, lineBreak: false });
    doc.font("Helvetica-Bold").fontSize(9).fillColor(COLORS.ink)
      .text(String(row.item), itemX, rowY + 9, { width: itemWidth - 8, lineGap: 2 });
    doc.font("Helvetica").fontSize(9).fillColor(COLORS.body)
      .text(String(row.quantity), quantityX, rowY + 10, { width: quantityWidth, align: "center", lineBreak: false });
    doc.font("Helvetica").fontSize(9).fillColor(COLORS.body)
      .text(typeof row.price === "number" ? formatMoney(row.price) : String(row.price), priceX, rowY + 10, {
        width: priceWidth, align: "right", lineBreak: false,
      });
    doc.y = rowY + rowHeight;
  });
  doc.y += 18;
}

function resolvePlanPrice(quotation) {
  const explicitPrice = [quotation.planPrice, quotation.details?.planPrice]
    .find((value) => value !== undefined && value !== null && Number.isFinite(Number(value)));
  if (explicitPrice !== undefined) return Number(explicitPrice);

  const key = `${quotation.serviceSlug || ""}:${quotation.planSlug || ""}`;
  return PLAN_PRICE_FALLBACKS[key] ?? null;
}

function drawFixedItems(doc, quotation) {
  const price = resolvePlanPrice(quotation);
  drawPricingTable(doc, quotation, [{
    item: quotation.planName || humanize(quotation.planSlug || "Plan"),
    quantity: 1,
    price: price == null ? "-" : price,
  }]);
}

function drawPriceAndNotes(doc, quotation) {
  ensureSpace(doc, 175, quotation);
  const top = doc.y;
  const totalWidth = 232;
  const gap = 18;
  const notesWidth = CONTENT_WIDTH - totalWidth - gap;
  const totalX = LEFT + notesWidth + gap;
  const noteText = quotation.adminNote ||
    "This quotation is based on the services and selections listed above. Final scope and delivery details will be confirmed by our team.";
  doc.font("Helvetica");
  const noteHeight = doc.heightOfString(noteText, {
    width: notesWidth - 26,
    fontSize: 8.5,
    lineGap: 2,
  });
  const panelHeight = Math.max(142, noteHeight + 52);

  doc.font("Helvetica-Bold").fontSize(8).fillColor(COLORS.goldDark)
    .text("NOTES", LEFT, top, { characterSpacing: 0.8 });
  doc.font("Helvetica").fontSize(8.5).fillColor(COLORS.body)
    .text(noteText, LEFT, top + 18, { width: notesWidth - 12, lineGap: 2 });

  doc
    .roundedRect(totalX, top - 4, totalWidth, panelHeight, 9)
    .fillAndStroke(COLORS.pale, COLORS.border);

  const planPrice = resolvePlanPrice(quotation);
  const rows = quotation.quotationType === "quick_quote"
    ? [["Plan price", planPrice]]
    : [
        ["Subtotal", quotation.subtotal],
        ["CGST", quotation.cgst],
        ["SGST", quotation.sgst],
        ["IGST", quotation.igst],
      ].filter(([, value]) => value !== undefined && value !== null && Number(value) !== 0);
  if (rows.length === 0 && planPrice !== null) rows.push(["Plan price", planPrice]);
  let rowY = top + 12;
  rows.forEach(([label, value]) => {
    doc.font("Helvetica").fontSize(8.5).fillColor(COLORS.body)
      .text(label.toUpperCase(), totalX + 13, rowY, { width: 105 });
    doc.font("Helvetica-Bold").fontSize(8.5).fillColor(COLORS.ink)
      .text(value != null ? formatMoney(value) : "To be confirmed", totalX + 118, rowY, {
        width: totalWidth - 135,
        align: "right",
      });
    rowY += 22;
  });

  const grandTotal = quotation.quotationType === "quick_quote"
    ? planPrice
    : quotation.grandTotal ?? planPrice;
  const totalBandY = top + panelHeight - 47;
  doc.roundedRect(totalX + 8, totalBandY, totalWidth - 16, 38, 5).fill(COLORS.ink);
  doc.font("Helvetica-Bold").fontSize(8).fillColor(COLORS.white)
    .text("TOTAL PAYABLE", totalX + 20, totalBandY + 15, { characterSpacing: 0.45 });
  doc.font("Helvetica-Bold").fontSize(12).fillColor(COLORS.gold)
    .text(grandTotal != null ? formatMoney(grandTotal) : "To be confirmed", totalX + 105, totalBandY + 13, {
      width: totalWidth - 125,
      align: "right",
    });

  doc.y = top + panelHeight + 18;
}

function drawQuotationDoc(doc, quotation) {
  drawPageHeader(doc, quotation);
  drawInfoCards(doc, quotation);

  if (quotation.quotationType === "quick_quote") {
    drawFixedItems(doc, quotation);
  } else {
    drawPricingTable(doc, quotation, getCustomPricingRows(quotation));
  }
  drawPriceAndNotes(doc, quotation);

  const range = doc.bufferedPageRange();
  for (let index = range.start; index < range.start + range.count; index += 1) {
    doc.switchToPage(index);
    drawFooter(doc, index + 1, range.count);
  }
}

function generateQuotationPdf(quotation, res) {
  const doc = new PDFDocument({
    size: "A4",
    margin: 46,
    bufferPages: true,
  });
  doc.pipe(res);
  drawQuotationDoc(doc, quotation);
  doc.end();
}

function generateQuotationPdfBuffer(quotation) {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({
      size: "A4",
      margin: 46,
      bufferPages: true,
    });
    const chunks = [];

    doc.on("data", (chunk) => chunks.push(chunk));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);

    drawQuotationDoc(doc, quotation);
    doc.end();
  });
}

module.exports = { generateQuotationPdf, generateQuotationPdfBuffer };
